contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry carrying all logic
    function run(address newDistributeAddr) public payable {
        require(true);

        // Read initial observables
        uint256 beforeBalance = c.balanceOf(address(c));
        address beforeDistribute = c.call{value:0}(abi.encodeWithSignature("distributeAddress()"))
            .length == 0 ? address(0) : address(0);
        // Note: distributeAddress is private in C so can't call; we will treat it as unknown.

        // We will try to set caller (cfo) and set distribute address via setCaller and setDistributeAddress flow.
        // First, set this contract as owner-called setter of cfo by calling setCaller from owner (owner is deployer of c)
        // However our caller is InvMutTest, which is the deployer of c per harness description.

        // Make this contract the caller (cfo)
        c.setCaller(address(this));

        // Set distributeAddress to a chosen address
        c.setDistributeAddress(newDistributeAddr);

        // Ensure contract has at least distributeAmount by transferring tokens from msg.sender (owner) to c if possible
        // msg.sender here is the InvMutTest runner; the deployed C minted initial supply to the deployer (the harness),
        // so InvMutTest (which deployed C) should hold initial supply. Transfer distributeAmount to c.
        uint256 distAmt = 2000 * 1e18;
        // transfer tokens from this contract (InvMutTest) to c
        c.transfer(address(c), distAmt);

        // Now attempt to call distributeTokenPeriodic and catch if it reverts
        bool reverted;
        try c.distributeTokenPeriodic() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call, read contract balance again
        uint256 afterBalance = c.balanceOf(address(c));

        // If the call did not revert then either it transferred distributeAmount out or it reverted earlier due to time/initTime
        // The rule: if distributeAmount was available and distributeAddress was set and the call did NOT revert then the contract balance decreased by exactly distributeAmount.
        // Because distributeAddress is external, we observe only balances: ensure afterBalance == beforeBalance - distAmt when not reverted.

        assert(reverted || afterBalance + distAmt == beforeBalance);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry carrying all logic
    // newDistributeAddr: address to set as distributeAddress
    function run(address newDistributeAddr) public payable {
        require(newDistributeAddr != address(0));

        // Observables before any state change
        uint256 beforeBalance = c.balanceOf(address(c));
        uint256 distributeAmount = 2000 * 1e18;

        // Make this contract the caller (cfo) so it can set distributeAddress and call distributeToken
        // setCaller is onlyOwner; InvMutTest is the deployer/owner of C per harness description
        c.setCaller(address(this));

        // set the distribute address to a chosen external address
        c.setDistributeAddress(newDistributeAddr);

        // Ensure the contract has at least distributeAmount by transferring tokens from this (owner) to c if possible
        // Transfer only if this contract has enough balance. If transfer reverts, the try/catch will mark as reverted.
        bool transferReverted = false;
        uint256 myBalance = c.balanceOf(address(this));
        if (myBalance >= distributeAmount) {
            try c.transfer(address(c), distributeAmount) {
                transferReverted = false;
            } catch {
                transferReverted = true;
            }
        }

        // Attempt to call distributeTokenPeriodic and capture whether it reverted
        bool callReverted;
        try c.distributeTokenPeriodic() {
            callReverted = false;
        } catch {
            callReverted = true;
        }

        // Read after-balance
        uint256 afterBalance = c.balanceOf(address(c));

        // Assert the invariant: if call did not revert, then previously distributeAddress was set (we set it) and
        // contract had at least distributeAmount (either from before or we transferred it) and therefore the contract's balance decreased by exactly distributeAmount.
        // Otherwise (call reverted) we make no claim about balances.
        assert(callReverted || afterBalance + distributeAmount == beforeBalance || (myBalance >= distributeAmount && transferReverted && afterBalance + distributeAmount == beforeBalance - 0));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry carrying all logic
    // dst: address to become distributeAddress; transferFromOwner: whether this test will try to fund the contract
    function run(address dst, bool transferFromOwner) public payable {
        require(dst != address(0));

        uint256 distributeAmount = 2000 * 1e18;

        // record contract balance before any changes
        uint256 beforeContractBalance = c.balanceOf(address(c));

        // Make this contract the caller (cfo) so it can set distributeAddress and call distributeToken
        c.setCaller(address(this));

        // set the distribute address to dst
        c.setDistributeAddress(dst);

        // Optionally fund the contract by transferring tokens from owner (this) to c.
        // We perform the transfer as a top-level call if requested and only when balance allows.
        uint256 myBal = c.balanceOf(address(this));
        if (transferFromOwner && myBal >= distributeAmount) {
            c.transfer(address(c), distributeAmount);
        }

        // Attempt to call distributeToken and capture whether it reverted
        bool reverted;
        try c.distributeToken() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances after
        uint256 afterContractBalance = c.balanceOf(address(c));
        uint256 dstBalance = c.balanceOf(dst);

        // If the call did not revert then: distributeAddress was set (we set it), and the contract must have had >= distributeAmount
        // and as a result contract balance decreased by exactly distributeAmount and dst received exactly distributeAmount.
        // Otherwise (reverted) we make no claim about balances.
        assert(reverted || (beforeContractBalance >= distributeAmount && beforeContractBalance - afterContractBalance == distributeAmount && dstBalance >= distributeAmount));
    }

    receive() external payable {}
}

