contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take as parameters: the distributeAddress to set, an amount to ensure contract has enough tokens,
    // and a timestamp advance flag simulated by requiring now to be greater than initTime via calling distributeTokenPeriodic twice (first to set initTime).
    function run(address addr, uint256 topUpAmount) public payable {
        require(addr != address(0));
        // 1) Deploy-time owner of c is this contract's deployer (per problem). We need a caller with onlyCaller role to set distributeAddress.
        // The test contract is NOT the owner of c so setCaller must be called by owner; however constructor of C set msg.sender as owner (test harness deploys c),
        // and our InvMutTest was constructed with that c by the harness, so this contract is NOT owner. Therefore we cannot call onlyCaller functions.
        // Instead we observe public functions only: setDistributeAddress is onlyCaller, so we cannot call it. But we can still test distributeTokenPeriodic which reads distributeAddress and balance.
        // To make the property provable without privileged calls, require that distributeAddress is already set to addr by the harness (allowed by precondition here).
        // We enforce that by requiring c.distributeAddress() equals addr via the public getter.
        // Note: distributeAddress is a private variable in C, so there's no getter; instead we cannot read it. Adjust approach: rely on behavior that distributeTokenPeriodic requires contract balance >= distributeAmount and distributes to a non-zero distributeAddress. We cannot set distributeAddress, so restrict test to the case where calling distributeTokenPeriodic reverts iff distributeAddress is zero or insufficient balance or time not passed.
        // We'll check the observable effect: when distributeTokenPeriodic does NOT revert, the balance of c decreases by distributeAmount and the balance of this test contract's address does not change (since transfer is to distributeAddress). We can only observe address(c).balance (ETH) and ERC20 balances via c.balanceOf which is public. C is ERC20 so balanceOf is accessible.

        // Precondition: topUpAmount >= 0. We require topUpAmount to be at least 0 and small enough to not overflow when minting via no method exists; we cannot mint. So we can only observe current balances. To make a provable rule, we will call distributeTokenPeriodic and capture whether it reverts; if it succeeds, then the token balance of C must have decreased by c.distributeAmount (which is private, but distributeAmount is private; however distributeAmount is a visible literal in the contract: declared as 'uint256 distributeAmount = 2000 * 1e18;'. It's private so no getter. We must not reference it. But we can instead assert that when distributeTokenPeriodic succeeds, the balance of the contract decreased and the recipient gained that exact amount. But we cannot read distributeAddress to know recipient. So this is tough.

        // Simpler rule: calling distributeTokenPeriodic either reverts, or it preserves totalSupply (since transfer uses super._transfer, totalSupply unchanged). totalSupply is public. So assert that totalSupply remains the same after call regardless of revert.

        uint256 beforeTotal = c.totalSupply();
        bool reverted;
        try c.distributeTokenPeriodic() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterTotal = c.totalSupply();

        // General rule: distributeTokenPeriodic does not change totalSupply (burn/mint not involved in that function)
        assert(afterTotal == beforeTotal);
    }

    receive() external payable {}
}

